const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);

const startDate = yesterday.toISOString().split('T')[0];
const endDate = now.toISOString().split('T')[0];

console.log(`Generating performance report for ${startDate}`);

return {
  json: {
    start_date: startDate,
    end_date: endDate,
    report_type: 'daily'
  }
};

const metrics = $json.delivery_metrics;
const couriers = $json.courier_stats;
const timestamp = new Date().toISOString();
const reportDate = $('Set Date Range').first().json.start_date;

// Process courier performance
const courierList = couriers.couriers || [];
const topPerformers = courierList
  .sort((a, b) => (b.total_deliveries || 0) - (a.total_deliveries || 0))
  .slice(0, 5);

const needsImprovement = courierList
  .filter(c => (c.average_rating || 0) < 4.0)
  .sort((a, b) => (a.average_rating || 0) - (b.average_rating || 0))
  .slice(0, 3);

// Calculate bonus recommendations
const bonusRecommendations = topPerformers.map(courier => ({
  courier_name: courier.name,
  deliveries: courier.total_deliveries || 0,
  rating: courier.average_rating || 0,
  suggested_bonus: Math.round((courier.total_deliveries || 0) * 5) // $5 per delivery
}));

// Build report
const report = {
  report_date: reportDate,
  generated_at: timestamp,
  summary: {
    total_deliveries: metrics.total_deliveries || 0,
    completed_deliveries: metrics.completed_deliveries || 0,
    cancelled_deliveries: metrics.cancelled_deliveries || 0,
    average_delivery_time: metrics.average_delivery_time_minutes || 0,
    on_time_rate: metrics.on_time_percentage || 0
  },
  top_performers: topPerformers.map(c => ({
    name: c.name,
    deliveries: c.total_deliveries || 0,
    rating: c.average_rating || 0,
    earnings: c.total_earnings || 0
  })),
  needs_improvement: needsImprovement.map(c => ({
    name: c.name,
    rating: c.average_rating || 0,
    deliveries: c.total_deliveries || 0,
    issues: 'Low customer rating'
  })),
  bonus_recommendations: bonusRecommendations,
  total_bonus_pool: bonusRecommendations.reduce((sum, b) => sum + b.suggested_bonus, 0)
};

console.log(`Performance report generated for ${reportDate}`);
console.log(`Top performer: ${topPerformers[0]?.name || 'N/A'} with ${topPerformers[0]?.total_deliveries || 0} deliveries`);

return { json: report };

